private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    if (bb == null || sb == null) {
        throw new IllegalArgumentException("ByteBuffer and StringBuilder cannot be null");
    }
    if (i < 0 || i >= bb.remaining()) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }

    while (i < bb.remaining()) {
        byte b = bb.get(i);
        if (b >= 0) {
            sb.append((char) b);
            i++;
        } else {
            int octetCount = 0;
            if ((b & 0xE0) == 0xC0) {
                octetCount = 1;
            } else if ((b & 0xF0) == 0xE0) {
                octetCount = 2;
            } else if ((b & 0xF8) == 0xF0) {
                octetCount = 3;
            } else {
                throw new IllegalArgumentException("Invalid UTF-8 octet: " + b);
            }

            if (i + octetCount > bb.remaining()) {
                throw new IndexOutOfBoundsException("Not enough bytes for UTF-8 sequence");
            }

            int codePoint = 0;
            for (int j = 0; j <= octetCount; j++) {
                byte octet = bb.get(i + j);
                if (j == 0) {
                    codePoint = (octet & 0x1F) << (6 * (octetCount - j));
                } else {
                    codePoint |= (octet & 0x3F) << (6 * (octetCount - j));
                }
            }

            sb.appendCodePoint(codePoint);
            i += octetCount + 1;
        }
    }

    return i;
}
