@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    if (target == null || resultMap == null) {
        throw new IllegalArgumentException("Input parameters cannot be null");
    }

    // Get the vertices from the resultMap
    Set<V> vertices = resultMap.values();

    // Check if there are at least two vertices to form a bipartite graph
    if (vertices.size() < 2) {
        throw new IllegalArgumentException("At least two vertices are required to form a bipartite graph");
    }

    // Split the vertices into two sets
    Set<V> set1 = new HashSet<>();
    Set<V> set2 = new HashSet<>();
    Iterator<V> iterator = vertices.iterator();
    while (iterator.hasNext()) {
        V vertex = iterator.next();
        if (set1.size() <= set2.size()) {
            set1.add(vertex);
        } else {
            set2.add(vertex);
        }
    }

    // Add edges between the two sets
    for (V v1 : set1) {
        for (V v2 : set2) {
            target.addEdge(v1, v2);
        }
    }
}
