static long compressTimeBucket(long timeBucket, int dayStep) {
    try {
        // Extract the year, month, and day from the time bucket
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket % 10000) / 100);
        int day = (int) (timeBucket % 100);

        // Adjust the day based on the dayStep
        if (dayStep == 11) {
            if (day <= 5) {
                day = 1;
            } else if (day <= 15) {
                day = 12;
            } else {
                day = 23;
            }
        } else {
            throw new IllegalArgumentException("Unsupported dayStep: " + dayStep);
        }

        // Reconstruct the time bucket with the adjusted day
        return (long) year * 10000 + month * 100 + day;
    } catch (ArithmeticException e) {
        throw new IllegalArgumentException("Invalid timeBucket format: " + timeBucket, e);
    }
}
