private static String substituteVariables(String value, Properties props) {
    int startIndex = value.indexOf("${");
    while (startIndex != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex == -1) {
            break;
        }

        String variableName = value.substring(startIndex + 2, endIndex);
        String variableValue = props.getProperty(variableName);
        if (variableValue != null) {
            value = value.substring(0, startIndex) + variableValue + value.substring(endIndex + 1);
        }

        startIndex = value.indexOf("${", startIndex);
    }

    return value;
}
