            // Count class and array types
            count++;
            // Skip the rest of the class or array type
            while (c != ';') {
                c = descriptor.charAt(++count);
            }
        } else if (c == 'J' || c == 'D') {
            // Count long and double types
            count += 2;
        } else {
            // Count other types
            count++;
        }
    }

    // Pop the calculated number of types from the output frame stack
    // Assuming outputFrameStack is a valid stack and has enough elements
    for (int i = 0; i < count; i++) {
        outputFrameStack.pop();
    }
