public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }

    int capacity = desiredCapacity;
    boolean isPrime;

    do {
        isPrime = true;
        for (int i = 2; i <= Math.sqrt(capacity); i++) {
            if (capacity % i == 0) {
                isPrime = false;
                break;
            }
        }
        if (!isPrime) {
            capacity++;
        }
    } while (!isPrime);

    if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
        capacity = (int) (desiredCapacity * 1.11);
        do {
            isPrime = true;
            for (int i = 2; i <= Math.sqrt(capacity); i++) {
                if (capacity % i == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (!isPrime) {
                capacity++;
            }
        } while (!isPrime);
    }

    return capacity;
}
