public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder();
    boolean escapeNext = false;
    for (char c : str.toCharArray()) {
        if (escapeNext) {
            switch (c) {
                case 'b':
                    sb.append('\b');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'n':
                    sb.append('\n');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case '\"':
                    sb.append('"');
                    break;
                case '\'':
                    sb.append('\'');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    sb.append('\\').append(c);
                    break;
            }
            escapeNext = false;
        } else if (c == '\\') {
            escapeNext = true;
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}
