    if (root == null) {
        return 0;
    }

    // Step 2: Initialize a counter for the number of removed nodes
    int removedNodes = 0;

    // Step 3: Define a recursive method to traverse and remove inactive nodes
    root = removeInactiveNodesRecursively(root, removedNodes);

    // Step 4: Return the total number of removed nodes
    return removedNodes;
}

private Category removeInactiveNodesRecursively(Category node, int removedNodes) {
    if (node == null) {
        return null;
    }

    // Recursively remove inactive nodes from the left subtree
    node.left = removeInactiveNodesRecursively(node.left, removedNodes);

    // Recursively remove inactive nodes from the right subtree
    node.right = removeInactiveNodesRecursively(node.right, removedNodes);

    // Check if the current node is inactive
    if (!node.isActive()) {
        removedNodes++;
        return null; // Remove the inactive node
    }

    return node;
}
