private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList(Graph<Integer,E> graph) {
    List<Pair<List<Pair<Integer,Integer>>,E>> globalSeparatorList = new ArrayList<>();

    for (Edge<E> edge : graph.getEdges()) {
        List<Pair<Integer,Integer>> localSeparatorList = new ArrayList<>();

        for (Vertex<Integer> vertex : graph.getVertices()) {
            if (graph.hasEdge(vertex, edge.getSource()) && graph.hasEdge(vertex, edge.getTarget())) {
                List<Integer> neighbors = new ArrayList<>(graph.getNeighbors(vertex));
                neighbors.remove(edge.getSource());
                neighbors.remove(edge.getTarget());

                if (isSeparator(neighbors, edge.getSource(), edge.getTarget(), graph)) {
                    localSeparatorList.add(new Pair<>(vertex.getId(), vertex.getId()));
                }
            }
        }

        globalSeparatorList.add(new Pair<>(localSeparatorList, edge));
    }

    return globalSeparatorList;
}

private boolean isSeparator(List<Integer> neighbors, Integer source, Integer target, Graph<Integer,E> graph) {
    for (Integer neighbor : neighbors) {
        if (!isConnected(source, neighbor, target, graph)) {
            return true;
        }
    }

    return false;
}

private boolean isConnected(Integer source, Integer neighbor, Integer target, Graph<Integer,E> graph) {
    Set<Integer> visited = new HashSet<>();
    Queue<Integer> queue = new LinkedList<>();
    queue.add(source);
    visited.add(source);

    while (!queue.isEmpty()) {
        Integer current = queue.poll();

        for (Integer next : graph.getNeighbors(current)) {
            if (next.equals(target)) {
                return true;
            }

            if (!visited.contains(next) && !next.equals(neighbor)) {
                visited.add(next);
                queue.add(next);
            }
        }
    }

    return false;
}
