    // Calculate the number of bytes needed to represent the int
    int bytesNeeded = 4;

    // Ensure the byte vector is large enough to hold the int
    if (this.capacity - this.count < bytesNeeded) {
        // Calculate the new capacity (double the current capacity)
        int newCapacity = Math.max(this.capacity * 2, this.count + bytesNeeded);
        // Resize the byte vector
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.count);
        this.buffer = newBuffer;
        this.capacity = newCapacity;
    }

    // Convert the int to bytes and store them in the byte vector
    this.buffer[this.count++] = (byte) (intValue >> 24);
    this.buffer[this.count++] = (byte) (intValue >> 16);
    this.buffer[this.count++] = (byte) (intValue >> 8);
    this.buffer[this.count++] = (byte) intValue;

    return this;
}
