private List<Integer> computeLowerBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys list cannot be null or empty");
    }

    List<Integer> lowerBounds = new ArrayList<>();
    for (K key : keys) {
        try {
            // Assuming K has a method getLowerBound() that returns an Integer
            Integer lowerBound = key.getLowerBound();
            if (lowerBound != null) {
                lowerBounds.add(lowerBound);
            } else {
                throw new IllegalArgumentException("Lower bound for key " + key + " is null");
            }
        } catch (Exception e) {
            throw new RuntimeException("Error computing lower bound for key " + key, e);
        }
    }

    return lowerBounds;
}
