private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("The list of keys cannot be null or empty");
    }

    List<Integer> upperBounds = new ArrayList<>();
    for (K key : keys) {
        // Assuming K has a method getLowerBound() that returns the lower bound of the key
        int lowerBound = key.getLowerBound();
        // Assuming K has a method getUpperBound() that returns the upper bound of the key
        int upperBound = key.getUpperBound();
        // Compute the minimum upper bound for the key
        int minUpperBound = Math.min(upperBound, lowerBound);
        upperBounds.add(minUpperBound);
    }

    return upperBounds;
}
