private String buildContentRange() {
    // The 'Content-Range' header typically follows the format: "Content-Range: bytes start-end/total"
    // For simplicity, let's assume we are dealing with a range of bytes and the total size is known.
    // In a real-world scenario, you would need to determine the start, end, and total values dynamically.

    long start = 0; // Start of the range
    long end = 999; // End of the range
    long total = 1000; // Total size

    if (start < 0 || end < 0 || total < 0 || start > end || end > total) {
        throw new IllegalArgumentException("Invalid range values");
    }

    return "bytes " + start + "-" + end + "/" + total;
}
